<script setup lang="ts">
import type { DocumentRecord } from "../../api/documents";
defineProps<{ items: DocumentRecord[]; selectedId: number | null }>();
const emit = defineEmits<{ select: [item: DocumentRecord]; retryParse: [id: number]; retryIndex: [id: number] }>();
function status(document: DocumentRecord) { return document.parse_status === "failed" || document.index_status === "failed" ? "失败" : document.parse_status === "parsing" || document.index_status === "indexing" ? "运行中" : document.parse_status === "pending" || document.index_status === "pending" ? "排队" : "已完成"; }
</script>
<template><section class="task-list"><article v-for="item in items" :key="item.id" :class="{ selected: item.id === selectedId }" @click="emit('select', item)"><div><p class="type">文档解析 / 索引 · LIVE</p><h2>{{ item.file_path }}</h2><p>对象 #{{ item.id }} · 解析：{{ item.parse_status }} · 索引：{{ item.index_status }}</p></div><div class="status"><span :class="status(item)">{{ status(item) }}</span><small>{{ item.started_at || "开始时间未提供" }}</small></div><div class="actions"><button v-if="item.parse_status === 'failed'" @click.stop="emit('retryParse', item.id)">重试解析</button><button v-if="item.index_status === 'failed' || item.index_status === 'outdated'" @click.stop="emit('retryIndex', item.id)">重试索引</button></div></article><p v-if="!items.length" class="empty">当前没有可展示的文档处理状态。</p></section></template>
<style scoped>.task-list{display:grid;gap:.65rem}.task-list article{display:grid;grid-template-columns:minmax(0,1fr) 150px auto;gap:1rem;align-items:center;padding:.85rem 1rem;border:1px solid var(--border-subtle);border-radius:var(--radius-md);background:var(--paper);cursor:pointer}.task-list article.selected{border-color:var(--color-primary);box-shadow:inset 3px 0 var(--color-primary)}.type{margin:0;color:var(--color-primary);font-size:.72rem;font-weight:900;letter-spacing:.08em}.task-list h2{margin:.25rem 0;font-size:1rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.task-list p:last-child,.status small{color:var(--text-muted);font-size:.84rem}.status{display:grid;gap:.35rem}.status span{font-size:.82rem;font-weight:800}.status .失败{color:var(--color-danger)}.status .运行中{color:var(--color-primary)}.status .排队{color:var(--color-warning)}.actions button{border:1px solid var(--border-strong);border-radius:6px;padding:.45rem .6rem;background:var(--paper);font-weight:700}.empty{padding:1rem;border:1px dashed var(--border-strong);color:var(--text-muted)}@media(max-width:800px){.task-list article{grid-template-columns:1fr}.task-list h2{white-space:normal}}</style>
